import { generatePKCE } from "@openauthjs/openauth/pkce"

const CLIENT_ID = "9d1c250a-e61b-44d9-88ed-5944d1962f5e"

async function authorize(mode) {
  const pkce = await generatePKCE()
  const url = new URL(`https://${mode === "console" ? "console.anthropic.com" : "claude.ai"}/oauth/authorize`, import.meta.url)
  url.searchParams.set("code", "true")
  url.searchParams.set("client_id", CLIENT_ID)
  url.searchParams.set("response_type", "code")
  url.searchParams.set("redirect_uri", "https://console.anthropic.com/oauth/code/callback")
  url.searchParams.set("scope", "org:create_api_key user:profile user:inference")
  url.searchParams.set("code_challenge", pkce.challenge)
  url.searchParams.set("code_challenge_method", "S256")
  url.searchParams.set("state", pkce.verifier)
  return {
    url: url.toString(),
    verifier: pkce.verifier,
  }
}

async function exchange(code, verifier) {
  const splits = code.split("#")
  const result = await fetch("https://console.anthropic.com/v1/oauth/token", {
    method: "POST",
    headers: {
      "Content-Type": "application/json",
    },
    body: JSON.stringify({
      code: splits[0],
      state: splits[1],
      grant_type: "authorization_code",
      client_id: CLIENT_ID,
      redirect_uri: "https://console.anthropic.com/oauth/code/callback",
      code_verifier: verifier,
    }),
  })
  if (!result.ok) return { type: "failed" }
  const json = await result.json()
  return {
    type: "success",
    refresh: json.refresh_token,
    access: json.access_token,
    expires: Date.now() + json.expires_in * 1000,
  }
}

/** @type {import('@opencode-ai/plugin').Plugin} */
export async function HalloweedAnthropicAuthPlugin({ client }) {
  return {
    "experimental.chat.system.transform": (input, output) => {
      const prefix = "You are Claude Code, Anthropic's official CLI for Claude."
      if (input.model?.providerID === "anthropic") {
        output.system.unshift(prefix)
        if (output.system[1]) output.system[1] = prefix + "\n\n" + output.system[1]
      }
    },
    auth: {
      provider: "anthropic",
      async loader(getAuth, provider) {
        const auth = await getAuth()
        if (auth.type !== "oauth") return {}

        for (const model of Object.values(provider.models)) {
          model.cost = {
            input: 0,
            output: 0,
            cache: {
              read: 0,
              write: 0,
            },
          }
        }

        return {
          apiKey: "",
          async fetch(input, init) {
            const auth = await getAuth()
            if (auth.type !== "oauth") return fetch(input, init)

            if (!auth.access || auth.expires < Date.now()) {
              const response = await fetch("https://console.anthropic.com/v1/oauth/token", {
                method: "POST",
                headers: {
                  "Content-Type": "application/json",
                },
                body: JSON.stringify({
                  grant_type: "refresh_token",
                  refresh_token: auth.refresh,
                  client_id: CLIENT_ID,
                }),
              })
              if (!response.ok) throw new Error(`Token refresh failed: ${response.status}`)
              const json = await response.json()
              await client.auth.set({
                path: {
                  id: "anthropic",
                },
                body: {
                  type: "oauth",
                  refresh: json.refresh_token,
                  access: json.access_token,
                  expires: Date.now() + json.expires_in * 1000,
                },
              })
              auth.access = json.access_token
            }

            const req = init ?? {}
            const headers = new Headers()

            if (input instanceof Request) {
              input.headers.forEach((value, key) => {
                headers.set(key, value)
              })
            }

            if (req.headers) {
              if (req.headers instanceof Headers) {
                req.headers.forEach((value, key) => {
                  headers.set(key, value)
                })
              } else if (Array.isArray(req.headers)) {
                for (const [key, value] of req.headers) {
                  if (typeof value !== "undefined") headers.set(key, String(value))
                }
              } else {
                for (const [key, value] of Object.entries(req.headers)) {
                  if (typeof value !== "undefined") headers.set(key, String(value))
                }
              }
            }

            const incoming = headers.get("anthropic-beta") || ""
            const betas = incoming.split(",").map((item) => item.trim()).filter(Boolean)
            headers.set("authorization", `Bearer ${auth.access}`)
            headers.set("anthropic-beta", [...new Set(["oauth-2025-04-20", "interleaved-thinking-2025-05-14", ...betas])].join(","))
            headers.set("user-agent", "claude-cli/2.1.2 (external, cli)")
            headers.delete("x-api-key")

            const prefix = "mcp_"
            let body = req.body
            if (body && typeof body === "string") {
              try {
                const parsed = JSON.parse(body)

                if (parsed.system && Array.isArray(parsed.system)) {
                  parsed.system = parsed.system.map((item) => {
                    if (item.type === "text" && item.text) {
                      return {
                        ...item,
                        text: item.text.replace(/OpenCode/g, "Claude Code").replace(/opencode/gi, "Claude"),
                      }
                    }
                    return item
                  })
                }

                if (parsed.tools && Array.isArray(parsed.tools)) {
                  parsed.tools = parsed.tools.map((tool) => ({
                    ...tool,
                    name: tool.name ? `${prefix}${tool.name}` : tool.name,
                  }))
                }

                if (parsed.messages && Array.isArray(parsed.messages)) {
                  parsed.messages = parsed.messages.map((msg) => {
                    if (msg.content && Array.isArray(msg.content)) {
                      msg.content = msg.content.map((block) => {
                        if (block.type === "tool_use" && block.name) {
                          return {
                            ...block,
                            name: `${prefix}${block.name}`,
                          }
                        }
                        return block
                      })
                    }
                    return msg
                  })
                }

                body = JSON.stringify(parsed)
              } catch {
              }
            }

            let next = input
            let url = null
            try {
              if (typeof input === "string" || input instanceof URL) url = new URL(input.toString())
              if (input instanceof Request) url = new URL(input.url)
            } catch {
              url = null
            }

            if (url && url.pathname === "/v1/messages" && !url.searchParams.has("beta")) {
              url.searchParams.set("beta", "true")
              next = input instanceof Request ? new Request(url.toString(), input) : url
            }

            const response = await fetch(next, {
              ...req,
              body,
              headers,
            })

            if (!response.body) return response

            const reader = response.body.getReader()
            const decoder = new TextDecoder()
            const encoder = new TextEncoder()
            const stream = new ReadableStream({
              async pull(controller) {
                const { done, value } = await reader.read()
                if (done) {
                  controller.close()
                  return
                }
                let text = decoder.decode(value, { stream: true })
                text = text.replace(/"name"\s*:\s*"mcp_([^"]+)"/g, '"name": "$1"')
                controller.enqueue(encoder.encode(text))
              },
            })

            return new Response(stream, {
              status: response.status,
              statusText: response.statusText,
              headers: response.headers,
            })
          },
        }
      },
      methods: [
        {
          label: "Claude Pro/Max",
          type: "oauth",
          authorize: async () => {
            const result = await authorize("max")
            return {
              url: result.url,
              instructions: "Paste the authorization code here: ",
              method: "code",
              callback: async (code) => exchange(code, result.verifier),
            }
          },
        },
        {
          label: "Create an API Key",
          type: "oauth",
          authorize: async () => {
            const result = await authorize("console")
            return {
              url: result.url,
              instructions: "Paste the authorization code here: ",
              method: "code",
              callback: async (code) => {
                const credentials = await exchange(code, result.verifier)
                if (credentials.type === "failed") return credentials
                const created = await fetch("https://api.anthropic.com/api/oauth/claude_cli/create_api_key", {
                  method: "POST",
                  headers: {
                    "Content-Type": "application/json",
                    authorization: `Bearer ${credentials.access}`,
                  },
                }).then((response) => response.json())
                return { type: "success", key: created.raw_key }
              },
            }
          },
        },
        {
          provider: "anthropic",
          label: "Manually enter API Key",
          type: "api",
        },
      ],
    },
  }
}

export default HalloweedAnthropicAuthPlugin
